/* Additive question bank: existing IDs and answers stay unchanged. */
(function(root){
 const rows = [
 ['purpose','Easy','A user taps Submit in a trivia app, and the app displays their score. Which pair correctly identifies input and output?',['Tap on Submit → score displayed','Score displayed → tap on Submit','Submit button’s color → source-code comment','App’s title → screen ID'],'The tap is an action supplied to the app; the displayed score is information the app produces.'],
 ['purpose','Medium','At a kiosk, a visitor selects Spanish and sees the instructions in Spanish. What is the input?',['The visitor’s language selection','The translated instructions','The kiosk’s screen brightness','The text of the source-code comments'],'The visitor supplies a language choice; the translated instructions are output.'],
 ['purpose','Hard','A school app displays today’s announcement at startup. A student then taps Listen, and the app plays a recording. Which statement is correct?',['Both the displayed announcement and the recording are outputs','Only the recording is output because it follows a tap','The announcement is input because it appears first','The Listen tap is output because it causes sound'],'Text and sound are both produced by the program. Output can occur at startup or after input.'],
 ['purpose','Medium','An emergency-drill app should tell students where to meet. Which result best demonstrates that it serves its purpose?',['Students can identify the correct meeting location','The app contains ten different sound files','The source code uses long element IDs','The developer can change its colors'],'Its purpose is to convey a meeting location, so successful user understanding is the relevant result.'],
 ['design','Easy','A cafeteria menu app is meant for students. The team watches students try to find vegetarian options before revising the screen. Which concept is best illustrated?',['User-centered design','Sequential execution','Random number generation','Single-line comments'],'The team observes intended users and uses their needs to guide the interface.'],
 ['design','Medium','Visitors repeatedly tap a decorative picture because they think it opens the map. Which revision best addresses the observed problem?',['Provide a clearly labeled View map button and make its role visually clear','Add a source-code comment explaining the picture','Make the decorative picture larger but keep it noninteractive','Remove the map screen'],'A clear control helps visitors distinguish actionable elements from decoration.'],
 ['design','Hard','A planner app is intended for new students. Experienced developers navigate it easily, but new students cannot find deadlines. Which evidence should guide the redesign?',['Observe new students trying to find deadlines and revise based on their difficulties','Only use the developers’ success as proof that navigation is clear','Select the version with the most screens','Ignore feedback until every color is finalized'],'User-centered design evaluates the interface with its intended audience and actual tasks.'],
 ['design','Medium','A team labels a transit app’s navigation buttons “1”, “2”, and “3”. Testers cannot predict their destinations. Which change most directly helps?',['Use labels such as Routes, Fares, and Help','Rename invisible IDs to longer numbers','Add more console messages','Replace all labels with identical icons'],'Descriptive visible labels communicate where navigation controls lead.'],
 ['sequence','Easy','At startup, a welcome app first displays a title, then changes the background, then logs Ready. The commands run one after another in written order. Which concept is illustrated?',['Sequential programming','User-centered design','Audio input','Documentation'],'Sequential programming executes statements in their specified order.'],
 ['sequence','Medium','A check-in app sets a label to “Checking”, then immediately sets the same label to “Welcome”. Both commands are outside handlers. What should remain when startup finishes?',['Welcome','Checking','CheckingWelcome','The name of the first event handler'],'The later sequential statement replaces the earlier value of that label’s text.'],
 ['sequence','Hard','A museum app runs the shown startup code. Assume its screen and label exist. What is true after startup finishes?',['The lobby screen is shown, its title says Welcome, and Ready was logged','The lobby title must say Loading because it was assigned first','Ready becomes the title automatically','The title changes only after the first visitor tap'],'The statements run in order, and the final title assignment replaces Loading.','setProperty("lobbyTitle", "text", "Loading");\nsetScreen("lobbyScreen");\nconsole.log("Ready");\nsetProperty("lobbyTitle", "text", "Welcome");'],
 ['sequence','Medium','A teammate writes “Make the screen cheerful” as an instruction for a computer. Why is a specific command such as setProperty needed to implement it?',['The computer needs precise instructions and property values','Natural-language descriptions automatically execute in App Lab','All programming instructions must contain a click event','Comments determine colors without commands'],'A human goal must be translated into instructions that follow the programming environment’s rules.'],
 ['events','Easy','A visitor clicks the Directions button in a campus app. Which part is the event?',['The click on Directions','The app’s source-code comment','The spelling of the screen ID','The developer’s planning notes'],'A click is an occurrence the program can listen for and respond to.'],
 ['events','Medium','In a ticket app, clicking Confirm makes the confirmation screen appear. Which part is the event handler?',['The code that responds to the Confirm click by changing screens','The physical click itself','The visible word Confirm','The confirmation screen’s background color'],'The click is the event; the responding code is the event handler.'],
 ['events','Hard','A help app logs Ready at startup. Later, each click on Help opens a help screen. Which description best fits?',['An event-driven app with a sequential startup statement','A purely sequential app that never responds to events','An app where every command waits for a Help click','An app where comments trigger screen changes'],'Event-driven programs can include startup statements and handlers that respond later.'],
 ['events','Medium','A volunteer app’s map should open only when users tap Find us. The developer put setScreen at the top level, and the map opens immediately. Which change fixes the timing?',['Place setScreen inside the Find us click handler','Change the map screen’s background','Add a comment above setScreen','Rename the app to Volunteer Map'],'Top-level statements run at startup; handler statements run when the matching event occurs.'],
 ['properties','Easy','A school app should change an existing banner label to “School closed”. Which command fits?',['setProperty("banner", "text", "School closed");','setScreen("School closed");','console.log("School closed");','setProperty("text", "banner", "School closed");'],'setProperty targets banner, selects its text property, and supplies the desired text.'],
 ['properties','Medium','A museum app has a button with ID audioButton and visible text “Listen”. Which statement changes that button’s text to “Play tour”?',['setProperty("audioButton", "text", "Play tour");','setProperty("Listen", "text", "Play tour");','setScreen("audioButton");','console.log("Play tour");'],'The command uses the element’s ID, not its current visible text.'],
 ['properties','Hard','A club app changes a notice label’s text and then its text color. After the shown code finishes, what is true?',['The notice says Meeting moved and its text is red','Changing text color erases the notice text','The notice says red in its original color','Both commands change the label’s ID'],'These statements update two separate properties of the same element.','setProperty("notice", "text", "Meeting moved");\nsetProperty("notice", "text-color", "red");'],
 ['properties','Medium','A walking-tour app needs to make its existing Next button easier to tap by setting its width to 140. Which command does that?',['setProperty("nextButton", "width", 140);','setProperty("nextButton", "text", "140");','setScreen("nextButton");','onEvent("nextButton", "width", function() {});'],'The width property takes a numeric size; changing button text does not set its width.'],
 ['commands','Easy','A study-break app plays a chime when a user taps Finished. Which part is output?',['The chime heard by the user','The tap on Finished','The handler’s element ID','The developer selecting a toolbox block'],'Audio produced by a program is output.'],
 ['commands','Medium','A scavenger-hunt app needs a random station number from 1 through 8, including both ends. Which expression fits?',['randomNumber(1, 8)','randomNumber(0, 8)','randomNumber(1, 7)','randomNumber(8, 8)'],'The specified range includes all eight station numbers and excludes zero.'],
 ['commands','Hard','A team uses console.log("Ticket ready") after a purchase button is clicked, but customers see no confirmation label. What explains the observation?',['console.log writes to the Debug Console rather than updating the customer’s label','console.log always waits until the app closes','A click event prevents all text output','Quoted strings cannot be used for confirmation text'],'To show a message in the interface, update a screen element; a debug message alone does not do that.'],
 ['commands','Medium','A clinic app’s Home button should return to welcomeScreen. Assume both elements exist. Which code accomplishes the task?',['onEvent("homeButton", "click", function() { setScreen("welcomeScreen"); });','onEvent("welcomeScreen", "click", function() { setScreen("homeButton"); });','console.log("welcomeScreen");','setProperty("homeButton", "text", "welcomeScreen");'],'The handler listens for the button click and selects the destination screen by its ID.'],
 ['documentation','Easy','A developer leaves a note explaining why the Back button returns to the menu. The note starts with //. What is it?',['A comment','An input event','A screen element','A sound command'],'A // note outside a string is a comment for people reading the source.'],
 ['documentation','Medium','A new teammate needs to understand which screens each button opens. Which addition best helps them maintain the app?',['Documentation describing navigation and the purpose of the handlers','A louder startup sound','Random background changes','Shorter, unexplained button labels'],'Documentation explains the program’s structure and intent for people working on it.'],
 ['documentation','Hard','A developer changes a comment from “Open help” to “Open menu” but leaves setScreen("helpScreen") unchanged. What happens on the next matching click?',['The app still opens helpScreen','The app opens menuScreen because the comment changed','The handler no longer executes','The comment is displayed as a button label'],'Comments do not change execution; the command still selects helpScreen.'],
 ['documentation','Medium','A team wants an app label to display the words Welcome back. How should those words be supplied to setProperty?',['As a quoted string, "Welcome back"','As an unquoted phrase, Welcome back','As a comment, // Welcome back','As the event type, "click"'],'Text values are represented as strings with matching quotation marks.'],
 ['debugging','Easy','A developer reproduces a bug where Back opens the wrong page, corrects the screen ID, and tests again. Which concept best names finding and fixing that fault?',['Debugging','Audio output','Randomization','User input'],'Finding the cause of incorrect behavior and fixing it is debugging.'],
 ['debugging','Medium','A lunch-menu team releases a prototype, gathers feedback, improves the layout, and tests the revised version. Which process is illustrated?',['Iterative development','Executing one program statement','Generating an integer','Commenting out every event handler'],'The team repeats a build, test, and revise cycle.'],
 ['debugging','Hard','A bus app occasionally places a stop icon partly offscreen. The random x range includes positions too far right. What is the most useful next step?',['Restrict the range using the screen and icon widths, then test multiple runs','Test once and assume all future positions are safe','Rename the icon without changing the range','Only add a comment saying the icon must stay onscreen'],'A random-placement bug requires correcting the possible positions and testing more than one outcome.'],
 ['debugging','Medium','A travel app’s button works on the first screen but fails after visiting Help. Which test is most likely to reproduce the reported problem?',['Start on the first screen, visit Help, return, then try the button','Inspect only the button’s font','Open the app and close it without clicking','Click an unrelated button once'],'Reproducing the tester’s sequence gives evidence about when the failure happens.']
 ];
 root.QUESTIONS.push(...rows.map((r,i)=>({id:'scenario-'+String(i+1).padStart(2,'0'),topic:r[0],difficulty:r[1],question:r[2],choices:r[3],correctAnswer:0,explanation:r[4],code:r[5]||null,kind:'scenario'})));
})(typeof window==='undefined'?globalThis:window);
